import http from "http";
import { ImpressionBatcher } from "./impressionBatcher";

export function createIngestServer(batcher: ImpressionBatcher): http.Server {
  return http.createServer((req, res) => {
    if (req.method !== "POST" || req.url !== "/v1/impressions") {
      res.writeHead(404).end();
      return;
    }
    const chunks: Buffer[] = [];
    let size = 0;
    req.on("data", (c: Buffer) => {
      size += c.length;
      if (size > 64 * 1024) {
        res.writeHead(413).end();
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on("end", () => {
      try {
        const body = JSON.parse(Buffer.concat(chunks).toString("utf8"));
        if (!Array.isArray(body.events)) throw new Error("events must be an array");
        for (const e of body.events) batcher.add(e);
        res.writeHead(202, { "content-type": "application/json" }).end('{"accepted":true}');
      } catch (err) {
        res.writeHead(400).end(JSON.stringify({ error: (err as Error).message }));
      }
    });
  });
}

export interface Impression {
  campaignId: string;
  creativeId: string;
  placement: string;
  ts: number;
}

export interface WarehouseSink {
  insert(rows: Impression[]): Promise<void>;
}

export class ImpressionBatcher {
  private buffer: Impression[] = [];
  private timer: NodeJS.Timeout | null = null;
  private flushing: Promise<void> = Promise.resolve();

  constructor(private sink: WarehouseSink, private maxBatch = 500, private intervalMs = 5_000) {}

  start(): void {
    this.timer = setInterval(() => void this.flush(), this.intervalMs);
  }

  add(e: Impression): void {
    this.buffer.push(e);
    if (this.buffer.length >= this.maxBatch) void this.flush();
  }

  flush(): Promise<void> {
    this.flushing = this.flushing.then(async () => {
      if (this.buffer.length === 0) return;
      const rows = this.buffer;
      this.buffer = [];
      try {
        await this.sink.insert(rows);
      } catch (err) {
        console.error("impression flush failed, requeueing", rows.length, err);
        this.buffer = rows.concat(this.buffer);
      }
    });
    return this.flushing;
  }

  async stop(): Promise<void> {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    await this.flush();
  }
}

import { createIngestServer } from "./ingestServer";
import { ImpressionBatcher, WarehouseSink } from "./impressionBatcher";

const SHUTDOWN_DEADLINE_MS = 20_000;

export function main(sink: WarehouseSink) {
  const batcher = new ImpressionBatcher(sink);
  batcher.start();
  const server = createIngestServer(batcher);
  server.keepAliveTimeout = 5_000;
  server.listen(Number(process.env.PORT ?? 8080));

  let shuttingDown = false;
  const shutdown = async (signal: string) => {
    if (shuttingDown) return;
    shuttingDown = true;
    console.log(`received ${signal}, draining`);
    const killer = setTimeout(() => {
      console.error("shutdown deadline exceeded, exiting");
      process.exit(1);
    }, SHUTDOWN_DEADLINE_MS);
    killer.unref();

    await batcher.stop();
    await new Promise<void>((resolve) => server.close(() => resolve()));
    server.closeIdleConnections();

    clearTimeout(killer);
    process.exit(0);
  };

  process.on("SIGTERM", () => void shutdown("SIGTERM"));
  process.on("SIGINT", () => void shutdown("SIGINT"));
}
